install:
set -e
trap 'rm -rf "$HOME/.cache/tmp" "$HOME/.cache/gradle-9.3.1-bin.zip"' EXIT
[ -f "$HOME/.bashrc" ] || : > "$HOME/.bashrc"
sed -i '/case \$- in/,/esac/d' "$HOME/.bashrc" 2>/dev/null || true
export ANDROID_HOME="${ANDROID_HOME:-/opt/android-sdk}"
GRADLE_DIR="$HOME/.local/share/gradle/gradle-9.3.1"
export PATH="$GRADLE_DIR/bin:$ANDROID_HOME/cmdline-tools/latest/bin:$ANDROID_HOME/platform-tools:$PATH"
if [ ! -x "$GRADLE_DIR/bin/gradle" ]; then
  mkdir -p "$HOME/.local/share/gradle" "$HOME/.cache"
  curl -fsSL https://services.gradle.org/distributions/gradle-9.3.1-bin.zip -o "$HOME/.cache/gradle-9.3.1-bin.zip"
  python3 -m zipfile -e "$HOME/.cache/gradle-9.3.1-bin.zip" "$HOME/.local/share/gradle"
  chmod +x "$GRADLE_DIR/bin/gradle"
  rm -f "$HOME/.cache/gradle-9.3.1-bin.zip"
fi
grep -qF 'ANDROID_HOME=' "$HOME/.bashrc" || echo 'export ANDROID_HOME="${ANDROID_HOME:-/opt/android-sdk}"' >> "$HOME/.bashrc"
grep -qF 'gradle-9.3.1/bin' "$HOME/.bashrc" || echo 'export PATH="$HOME/.local/share/gradle/gradle-9.3.1/bin:$ANDROID_HOME/cmdline-tools/latest/bin:$ANDROID_HOME/platform-tools:$PATH"' >> "$HOME/.bashrc"
if command -v sudo >/dev/null 2>&1 && sudo -n true 2>/dev/null; then
  sudo mkdir -p /usr/share/gradle/bin /usr/local/bin
  sudo ln -sfn "$GRADLE_DIR/bin/gradle" /usr/share/gradle/bin/gradle
  sudo ln -sfn "$GRADLE_DIR/bin/gradle" /usr/local/bin/gradle
fi
if command -v sdkmanager >/dev/null 2>&1 && [ -w "$ANDROID_HOME" ] && { [ ! -d "$ANDROID_HOME/platforms/android-36.1" ] || [ ! -d "$ANDROID_HOME/build-tools/36.0.0" ] || [ ! -d "$ANDROID_HOME/build-tools/36.1.0" ]; }; then
  mkdir -p "$HOME/.cache/tmp"
  (yes || true) | TMPDIR="$HOME/.cache/tmp" JAVA_TOOL_OPTIONS="-Djava.io.tmpdir=$HOME/.cache/tmp -Djava.awt.headless=true" sdkmanager --sdk_root="$ANDROID_HOME" "platforms;android-36.1" "build-tools;36.0.0" "build-tools;36.1.0" >/dev/null
  rm -rf "$HOME/.cache/tmp"
fi
if [ ! -f "$HOME/.gradle/init.d/maven-central-mirror.init.gradle.kts" ]; then
  mkdir -p "$HOME/.gradle/init.d"
  cat <<'EOF' > "$HOME/.gradle/init.d/maven-central-mirror.init.gradle.kts"
import org.gradle.api.artifacts.repositories.MavenArtifactRepository
import org.gradle.api.tasks.testing.Test

val gcsMavenCentralMirror = "https://maven-central.storage-download.googleapis.com/maven2/"
val gcsRobolectricRepoUrl = "https://maven-central.storage-download.googleapis.com/maven2"

fun MavenArtifactRepository.rewriteMavenCentralToGcsMirror() {
  val normalized = url.toString().trimEnd('/')
  if (
    normalized == "https://repo.maven.apache.org/maven2" ||
      normalized == "https://repo1.maven.org/maven2"
  ) {
    setUrl(gcsMavenCentralMirror)
  }
}

beforeSettings {
  pluginManagement.repositories.configureEach {
    if (this is MavenArtifactRepository) {
      rewriteMavenCentralToGcsMirror()
    }
  }
  dependencyResolutionManagement.repositories.configureEach {
    if (this is MavenArtifactRepository) {
      rewriteMavenCentralToGcsMirror()
    }
  }
}

allprojects {
  buildscript.repositories.configureEach {
    if (this is MavenArtifactRepository) {
      rewriteMavenCentralToGcsMirror()
    }
  }
  tasks.withType<Test>().configureEach {
    if (!systemProperties.containsKey("robolectric.dependency.repo.url")) {
      systemProperty("robolectric.dependency.repo.url", gcsRobolectricRepoUrl)
      systemProperty("robolectric.dependency.repo.id", "mavenCentral")
    }
  }
}
EOF
fi
if [ ! -f local.properties ] || ! grep -qxF "sdk.dir=$ANDROID_HOME" local.properties; then
  printf 'sdk.dir=%s\n' "$ANDROID_HOME" > local.properties
fi
if [ ! -f debug.keystore ]; then
  mkdir -p "$HOME/.cache/tmp"
  TMPDIR="$HOME/.cache/tmp" JAVA_TOOL_OPTIONS="-Djava.io.tmpdir=$HOME/.cache/tmp -Djava.awt.headless=true" keytool -genkeypair -noprompt -keystore debug.keystore -storepass android -alias androiddebugkey -keypass android -keyalg RSA -keysize 2048 -validity 10000 -dname "CN=Android Debug,O=Android,C=US"
  rm -rf "$HOME/.cache/tmp"
fi
mkdir -p "$HOME/.cache/tmp"
TMPDIR="$HOME/.cache/tmp" JAVA_TOOL_OPTIONS="-Djava.io.tmpdir=$HOME/.cache/tmp -Djava.awt.headless=true" "$GRADLE_DIR/bin/gradle" --no-daemon :app:compileDebugKotlin :app:compileDebugUnitTestKotlin
rm -rf "$HOME/.cache/tmp"
